#!/usr/bin/env bash
# Question 1: inventory cannot list Pods. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "monitoring" >/dev/null 2>&1 || kubectl get namespace "monitoring" >/dev/null
timeout 60 bash -c "until kubectl -n 'monitoring' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: ServiceAccount
metadata:
  name: inventory-sa
  namespace: monitoring
---
apiVersion: rbac.authorization.k8s.io/v1
kind: Role
metadata:
  name: inventory-reader
  namespace: monitoring
rules:
  - apiGroups: [""]
    resources: ["pods"]
    verbs: ["get", "list"]
---
apiVersion: rbac.authorization.k8s.io/v1
kind: RoleBinding
metadata:
  name: inventory-reader
  namespace: monitoring
roleRef:
  apiGroup: rbac.authorization.k8s.io
  kind: Role
  name: inventory-reader
subjects:
  - kind: ServiceAccount
    name: inventory-sa
    namespace: monitoring
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: inventory
  namespace: monitoring
spec:
  replicas: 0
  selector:
    matchLabels: { app: inventory }
  template:
    metadata:
      labels: { app: inventory }
    spec:
      serviceAccountName: inventory-sa
      containers:
        - name: reporter
          image: alpine:3.21
          env:
            - name: NS
              valueFrom: { fieldRef: { fieldPath: metadata.namespace } }
          command:
            - sh
            - -c
            - |
              D=/var/run/secrets/kubernetes.io/serviceaccount
              while true; do
                if [ ! -r \$D/token ]; then
                  echo "no token at \$D/token"
                elif out=\$(wget -q -O /dev/null --no-check-certificate --header "Authorization: Bearer \$(cat \$D/token)" https://kubernetes.default.svc/api/v1/namespaces/\$NS/pods 2>&1); then
                  echo 200
                else
                  echo "\$out"
                fi
                sleep 5
              done
EOF

(
case "${Q1_FAULT}" in
  role-verb)
    kubectl -n "monitoring" patch role "inventory-reader" --type=json -p '[{"op":"replace","path":"/rules/0/verbs","value":["get"]}]'
    ;;
  role-resource)
    kubectl -n "monitoring" patch role "inventory-reader" --type=json -p '[{"op":"replace","path":"/rules/0/resources","value":["pod"]}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_2}" in
  binding-subject-ns)
    kubectl -n "monitoring" patch rolebinding "inventory-reader" --type=json -p '[{"op":"replace","path":"/subjects/0/namespace","value":"default"}]'
    ;;
  binding-role-ref)
    kubectl -n "monitoring" delete rolebinding "inventory-reader"
    kubectl -n "monitoring" create rolebinding "inventory-reader" --role="inventory-viewer" --serviceaccount="monitoring:inventory-sa"
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_3}" in
  wrong-sa)
    kubectl -n "monitoring" set serviceaccount "deployment/inventory" default
    ;;
  automount-off)
    kubectl -n "monitoring" patch serviceaccount "inventory-sa" -p '{"automountServiceAccountToken":false}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
kubectl -n "monitoring" scale "deployment/inventory" --replicas=1
kubectl -n "monitoring" rollout status "deployment/inventory" --timeout=240s
for _ in $(seq 1 30); do
  line="$(kubectl -n "monitoring" logs "deployment/inventory" --tail=1 2>/dev/null)"
  [[ -n "$line" && "$line" != 200 ]] && break
  sleep 2
done
[[ "$(kubectl -n "monitoring" logs "deployment/inventory" --tail=1 2>/dev/null)" != 200 ]] || { echo "inventory still lists Pods" >&2; exit 1; }
)
